{"record":"parent_entry","position":{"parent_record":"response:00000000000000000025:0001:0000","subposition":null},"original_role":"assistant","source":"tool_call","trust":"untrusted","provenance":null,"content":"{\"kind\":\"tool_call\",\"id\":\"fc_01a17a795d9f770c9ce01b09a1523efa\",\"call_id\":\"call_01a17a795d9f770c9ce01b09a1523efa\",\"name\":\"write_file\",\"arguments\":\"{\\\"content\\\":\\\"-- Feature flags: panel is the single source of truth.\\\\n-- Apply after schema.sql (or run standalone on an existing DB).\\\\nCREATE TABLE IF NOT EXISTS feature_flags (\\\\n  key VARCHAR(255) PRIMARY KEY CHECK (key ~ '^[a-z][a-z0-9_.-]{1,63}$'),\\\\n  description TEXT NOT NULL DEFAULT '',\\\\n  value_type VARCHAR(20) NOT NULL DEFAULT 'boolean' CHECK (value_type IN ('boolean', 'variant')),\\\\n  default_value JSONB NOT NULL DEFAULT 'false',\\\\n  variants JSONB,\\\\n  fail_mode VARCHAR(10) NOT NULL DEFAULT 'closed' CHECK (fail_mode IN ('closed', 'open')),\\\\n  status VARCHAR(10) NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'archived')),\\\\n  expires_at TIMESTAMP WITH TIME ZONE,\\\\n  created_by UUID REFERENCES auth.users (id) ON DELETE SET NULL,\\\\n  created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,\\\\n  updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP\\\\n);\\\\n\\\\nCREATE TABLE IF NOT EXISTS feature_flag_rules (\\\\n  flag_key VARCHAR(255) NOT NULL REFERENCES feature_flags (key) ON DELETE CASCADE,\\\\n  environment VARCHAR(20) NOT NULL CHECK (environment IN ('development', 'staging', 'production')),\\\\n  enabled BOOLEAN NOT NULL DEFAULT FALSE,\\\\n  rollout_percentage INT NOT NULL DEFAULT 0 CHECK (rollout_percentage BETWEEN 0 AND 100),\\\\n  target_org_ids JSONB NOT NULL DEFAULT '[]',\\\\n  target_project_ids JSONB NOT NULL DEFAULT '[]',\\\\n  target_user_ids JSONB NOT NULL DEFAULT '[]',\\\\n  deny_user_ids JSONB NOT NULL DEFAULT '[]',\\\\n  updated_by UUID REFERENCES auth.users (id) ON DELETE SET NULL,\\\\n  updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,\\\\n  PRIMARY KEY (flag_key, environment)\\\\n);\\\\n\\\\nINSERT INTO feature_flags (key, description, default_value) VALUES\\\\n  ('discord_service_v2', 'New Discord command set (v2 commands).', 'false'),\\\\n  ('living_fleet', 'Living-fleet creature UX and mood engine.', 'false')\\\\nON CONFLICT (key) DO NOTHING;\\\\n\\\",\\\"path\\\":\\\"services/management-panel/db/migrations/001_feature_flags.sql\\\"}\"}","truncated":false}
{"record":"parent_entry","position":{"parent_record":"response:00000000000000000025:0001:0001","subposition":null},"original_role":"assistant","source":"tool_call","trust":"untrusted","provenance":null,"content":"{\"kind\":\"tool_call\",\"id\":\"fc_01a17a7966fe7491894aa049c935304b\",\"call_id\":\"call_01a17a7966fe7491894aa049c935304b\",\"name\":\"write_file\",\"arguments\":\"{\\\"content\\\":\\\"/**\\\\n * @file Typed client for the panel feature-flag evaluate endpoint.\\\\n * The browser only ever receives resolved values, never targeting rules.\\\\n */\\\\n\\\\nimport { apiClient } from './api';\\\\n\\\\nexport type FlagKey = 'discord_service_v2' | 'living_fleet' | (string & {});\\\\n\\\\ninterface EvaluateResponse {\\\\n  evaluatedAt: string;\\\\n  environment: string;\\\\n  flags: Record<string, boolean | string>;\\\\n}\\\\n\\\\nlet cache: { at: number; flags: Record<string, boolean | string> } | null = null;\\\\nconst TTL_MS = 30_000;\\\\n\\\\nexport async function fetchEvaluatedFlags(force = false): Promise<Record<string, boolean | string>> {\\\\n  if (!force && cache && Date.now() - cache.at < TTL_MS) return cache.flags;\\\\n  const res = await (apiClient as any).api.get<EvaluateResponse>('/api/feature-flags/evaluate');\\\\n  cache = { at: Date.now(), flags: res.data.flags || {} };\\\\n  return cache.flags;\\\\n}\\\\n\\\\nexport function readCachedFlag(key: string, fallback: boolean | string = false): boolean | string {\\\\n  if (cache && key in cache.flags) return cache.flags[key];\\\\n  return envFlagOverride(key, fallback);\\\\n}\\\\n\\\\n/** Local escape hatch for dev/incidents: VITE_FEATURE_FLAG_<KEY>. */\\\\nexport function envFlagOverride(key: string, fallback: boolean | string): boolean | string {\\\\n  try {\\\\n    const raw = (import.meta as any).env?.[`VITE_FEATURE_FLAG_${key.toUpperCase().replace(/[^A-Z0-9]/g, '_')}`];\\\\n    if (raw === 'true') return true;\\\\n    if (raw === 'false') return false;\\\\n    if (raw !== undefined) return raw;\\\\n  } catch {\\\\n    // non-browser / no env — fall through\\\\n  }\\\\n  return fallback;\\\\n}\\\\n\\\\nexport function invalidateFlagCache(): void {\\\\n  cache = null;\\\\n}\\\\n\\\",\\\"path\\\":\\\"services/management-panel/src/lib/feature-flags.ts\\\"}\"}","truncated":false}
{"record":"parent_entry","position":{"parent_record":"response:00000000000000000025:0001:0002","subposition":null},"original_role":"assistant","source":"tool_call","trust":"untrusted","provenance":null,"content":"{\"kind\":\"tool_call\",\"id\":\"fc_01a17a7974447630b426c69057afe143\",\"call_id\":\"call_01a17a7974447630b426c69057afe143\",\"name\":\"write_file\",\"arguments\":\"{\\\"content\\\":\\\"import { useCallback, useEffect, useState } from 'react';\\\\nimport { fetchEvaluatedFlags, readCachedFlag, invalidateFlagCache } from '../lib/feature-flags';\\\\n\\\\n/** Reactive boolean/variant flag for the current user. Resolves to `fallback` while loading. */\\\\nexport function useFeatureFlag(key: string, fallback: boolean | string = false): boolean | string {\\\\n  const [value, setValue] = useState<boolean | string>(() => readCachedFlag(key, fallback));\\\\n\\\\n  useEffect(() => {\\\\n    let live = true;\\\\n    fetchEvaluatedFlags()\\\\n      .then((flags) => {\\\\n        if (live) setValue(key in flags ? flags[key] : fallback);\\\\n      })\\\\n      .catch(() => {\\\\n        if (live) setValue(fallback);\\\\n      });\\\\n    const onChanged = () => {\\\\n      invalidateFlagCache();\\\\n      fetchEvaluatedFlags(true).then((flags) => {\\\\n        if (live) setValue(key in flags ? flags[key] : fallback);\\\\n      }).catch(() => {});\\\\n    };\\\\n    window.addEventListener('feature-flags:changed', onChanged);\\\\n    return () => {\\\\n      live = false;\\\\n      window.removeEventListener('feature-flags:changed', onChanged);\\\\n    };\\\\n  }, [key]);\\\\n\\\\n  const refresh = useCallback(async () => {\\\\n    invalidateFlagCache();\\\\n    const flags = await fetchEvaluatedFlags(true);\\\\n    setValue(key in flags ? flags[key] : fallback);\\\\n  }, [key, fallback]);\\\\n\\\\n  return value as boolean | string;\\\\n}\\\\n\\\",\\\"path\\\":\\\"services/management-panel/src/hooks/useFeatureFlag.ts\\\"}\"}","truncated":false}
